"""Decode the two saved D1 step-2 boundaries before tracing new computation."""

import hashlib
import json
from pathlib import Path
import sys

from rich.console import Console
import torch

from bio_inspired_nanochat.checkpoint_manager import require_complete_checkpoint
from scripts.e2e.scaleup_checkpoint_recovery import compare_state


def digest(path):
    with path.open("rb") as source:
        return hashlib.file_digest(source, "sha256").hexdigest()


left, right, out = map(Path, sys.argv[1:])
for directory in (left, right):
    require_complete_checkpoint(str(directory), 2)
weights = ["model_000002.pt", "optim_000002_rank0.pt", "optim_000002_rank1.pt"]
hashes = {name: [digest(directory / name) for directory in (left, right)] for name in weights}
shards = {}
for rank in (0, 1):
    name = f"train_000002_rank{rank}.pt"
    first, second = (torch.load(directory / name, weights_only=True, map_location="cpu", mmap=True)
                     for directory in (left, right))
    assert first.keys() == second.keys()
    fields = {}
    for field in first:
        stats = {"tensors": 0, "non_bitwise_tensors": 0, "max_abs_delta": 0.0, "mismatches": []}
        compare_state(first[field], second[field], field, exact=True, stats=stats)
        fields[field] = stats
    shards[str(rank)] = fields

report = {"weights_and_optimizer_sha256": hashes, "rank_shards": shards}
with out.open("x") as stream:
    json.dump(report, stream, indent=2, sort_keys=True)
    stream.write("\n")

Console().print_json(data={
    "matching_weights_and_optimizers": [name for name, pair in hashes.items() if pair[0] == pair[1]],
    "shard_differences": {rank: {name: data["mismatches"] for name, data in fields.items()
                                if data["mismatches"]} for rank, fields in shards.items()},
})

